using System;
using System.Collections.Generic;

class Program
{
    static bool IsPrime(int n)
    {
        if (n < 2)
        {
            return false;
        }
        for (int d = 2; d < n; d++)
        {
            if (n % d == 0)
            {
                return false;
            }
        }
        return true;
    }

    static int[] PrimesUpTo(int n)
    {
        List<int> result = new List<int>();
        for (int i = 2; i <= n; i++)
        {
            if (IsPrime(i))
            {
                result.Add(i);
            }
        }
        return result.ToArray();
    }
}

