using System;
using System.Collections.Generic;

class Program
{
    static bool IsLong(string password)
    {
        return password.Length >= 8;
    }

    static bool HasDigit(string password)
    {
        foreach (char ch in password)
        {
            if (ch >= '0' && ch <= '9')
            {
                return true;
            }
        }
        return false;
    }

    static bool HasUpper(string password)
    {
        foreach (char ch in password)
        {
            if (ch >= 'A' && ch <= 'Z')
            {
                return true;
            }
        }
        return false;
    }

    static string PasswordStrength(string password)
    {
        int score = 0;
        if (IsLong(password))
        {
            score = score + 1;
        }
        if (HasDigit(password))
        {
            score = score + 1;
        }
        if (HasUpper(password))
        {
            score = score + 1;
        }
        if (score == 3)
        {
            return "сильный";
        }
        if (score == 2)
        {
            return "средний";
        }
        return "слабый";
    }
}
